  values: ['scale 0.8 → 1', 'rotate -2° → 0', '0.6s back-out', '網点 8px グリッド'],
  valuesEn: ['scale 0.8 → 1', 'rotate -2° → 0', '0.6s back-out', 'dot grid 8px'],
