R({ id: 'rotating-letters-spring', dur: 4.0, ease: 'spring', spring: [300, 25, 1], still: 2.2,
  samplesJa: ['速い', '美しい'], samplesEn: ['fast', 'bold'],
  f(g, t, o) {
    const [A, B] = TXTS(o);
    const [LA, LB] = t02Two(g, A, B, { o, size: 40, maxW: 236, maxLines: 2, y: 104 });
    const T1 = .7, T2 = 2.7, gapW = .22, k = 300, c = 25;
    const wA = LA.width + 28, wB = LB.width + 28, hA = LA.height + LA.size * .18, hB = LB.height + LB.size * .18;
    const pw = track(t, [[0, wA], [T1 + gapW, wB], [T2 + gapW, wA]], k, c), ph = track(t, [[0, hA], [T1 + gapW, hB], [T2 + gapW, hA]], k, c), cy = 104;
    const px = W / 2 - pw / 2, py = cy - ph / 2;
    rr(g, px, py, pw, ph, 9, K.red);
    const st = n => n > 1 ? Math.min(.03, .3 / (n - 1)) : 0;
    const exitS = (Lt, T) => { const s = st(Lt.glyphs.length); glyphs(g, Lt, gl => { const e = spring(t - T - gl.i * s, k, c); return { dy: -1.2 * ph * e, a: 1 - clamp(e * 1.3), c: K.paper }; }); };
    const enterS = (Lt, T) => { const s = st(Lt.glyphs.length); glyphs(g, Lt, gl => { const e = spring(t - T - gl.i * s, k, c); return { dy: (1 - e) * ph, a: clamp(e * 1.6), c: K.paper }; }); };
    clip(g, px, py, pw, ph, () => {
      if (t < T1) plain(g, LA, K.paper);
      else if (t < T2) { exitS(LA, T1); enterS(LB, T1 + gapW); }
      else { exitS(LB, T2); enterS(LA, T2 + gapW); }
    });
    label(g, 'spring 300/25 · 1 文字ずつ');
    t02Read(g, 'interval 2000ms');
  },
  descEn: 'The word in the pill swaps on a timer: old letters exit upward, new letters spring up from below one at a time.',
  focus: 'mode="wait"：古い語が抜けきってから新しい語が入る。1 文字ずつ 30ms ずつ遅れ、減衰比 0.72 のバネでわずかに行き過ぎて止まる。枠の幅も同じバネで次の語に合わせる。',
  focusEn: 'mode="wait": the old word leaves completely before the new one enters. Letters lag 30ms each and land on a spring (damping ratio 0.72) with a slight overshoot. The pill width follows the same spring.',
  caution: '入れ替わる語は読み上げで連呼されないよう aria-live は使わず、全候補を visually-hidden で並べるか固定文にする。2 秒より速く回さない。',
  cautionEn: 'Do not put the rotating word in an aria-live region — list all options in visually-hidden text instead. Do not rotate faster than every 2 seconds.',
  values: ['y 100% → 0 → -120%', 'spring stiffness 300 / damping 25', '1 文字 30ms 差', 'interval 2000ms'],
  valuesEn: ['y 100% → 0 → -120%', 'spring stiffness 300 / damping 25', '30ms per letter', 'interval 2000ms'],
  duration: 450, easing: 'spring(300, 25)',
  feel: ['弾む', 'きびきび'], use: ['見出し', 'UI', '広告'],
  recipes: {
    motion: `import { AnimatePresence, motion } from 'motion/react';
const seg = new Intl.Segmenter('ja', { granularity: 'grapheme' });
function RotatingText({ words, interval = 2000 }) {
  const [i, setI] = useState(0);
  useEffect(() => { const id = setInterval(() => setI(v => (v + 1) % words.length), interval); return () => clearInterval(id); }, []);
  const chars = [...seg.segment(words[i])].map(s => s.segment);
  return (<motion.span layout className="pill" style={{ overflow: 'hidden', display: 'inline-flex' }}>
    <span className="sr-only">{words.join('、')}</span>
    <AnimatePresence mode="wait" initial={false}>
      <motion.span key={i} aria-hidden style={{ display: 'inline-flex' }}>
        {chars.map((c, j) => (
          <motion.span key={j} style={{ display: 'inline-block' }}
            initial={{ y: '100%', opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={{ y: '-120%', opacity: 0 }}
            transition={{ type: 'spring', damping: 25, stiffness: 300, delay: j * .03 }}>{c}</motion.span>
        ))}
      </motion.span>
    </AnimatePresence>
  </motion.span>);
}`,
    css: `/* CSS だけなら 2 語を重ねて交互に（文字ごとの --i で時間差） */
.rot .ch { display:inline-block; animation: in .45s cubic-bezier(.34,1.4,.64,1) both; animation-delay: calc(var(--i) * 30ms); }
.rot .out .ch { animation: out .3s ease-in both; animation-delay: calc(var(--i) * 30ms); }
@keyframes in  { from { transform: translateY(100%); opacity:0; } }
@keyframes out { to   { transform: translateY(-120%); opacity:0; } }
@media (prefers-reduced-motion: reduce) { .rot .ch { animation:none; } }`
  }
});

