// ぼかした文字のアルファを「しきい値」で二値化して描く（SVG feColorMatrix 0 0 0 255 -140 相当）
const t02Goo = { c: null };
function t02Gooey(g, draw) {
  try {
    const m = g.getTransform(), sc = Math.max(1, Math.min(2, Math.hypot(m.a, m.b)));
    const c = t02Goo.c || (t02Goo.c = document.createElement('canvas')), w = Math.round(W * sc), h = Math.round(H * sc);
    if (c.width !== w || c.height !== h) { c.width = w; c.height = h; }
    const lg = c.getContext('2d', { willReadFrequently: true });
    lg.setTransform(1, 0, 0, 1, 0, 0); lg.globalAlpha = 1; lg.filter = 'none'; lg.clearRect(0, 0, w, h);
    lg.setTransform(sc, 0, 0, sc, 0, 0);
    draw(lg);
    const id = lg.getImageData(0, 0, w, h), d = id.data;
    for (let i = 3; i < d.length; i += 4) { const a = d[i]; if (a) d[i] = a < 130 ? 0 : a > 150 ? 255 : (a - 130) * 12.75; }
    lg.putImageData(id, 0, 0);
    g.drawImage(c, 0, 0, W, H);
    return true;
  } catch (e) { return false; }
}

