// 7. 中央から復号
R({ id: 'decrypt-center', dur: 3.4, ease: 'linear', still: 2.5,
  f(g, t, o) {
    const L = layout(g, TXT(o), { o, size: 40, y: 92, spacing: .04 });
    const gs = L.glyphs.filter(q => !q.space), n = gs.length, tick = Math.floor(t / .05), mono = FAM(o, 'm');
    // 行ごとに、行の中心からの距離（字数単位）で確定順を決める
    const adv = gs.reduce((a, q) => a + q.w, 0) / Math.max(1, n) + L.spacing;
    const dOf = q => Math.abs(q.x - L.lines[q.li].x) / adv, rank = q => Math.floor(dOf(q) + .25);
    const maxR = Math.max(0, ...gs.map(rank)), steps = maxR + 1, step = clamp(1.2 / steps, .05, .2), r0 = .6;
    const front = Math.floor(clamp((t - r0) / step + 1, 0, steps)) - Math.floor(clamp((t - 2.95) / .35) * steps + 1e-9);
    // 中央のガイドと、確定した範囲のブラケット
    const lx = L.lines[0].x, top = L.top - 8, bot = L.top + L.height + 6;
    ln(g, lx, top - 10, lx, bot + 10, K.mute, 1, [2, 3]);
    let lo = Infinity, hi = -Infinity, done = 0;
    gs.forEach(gl => {
      const r = rank(gl), ok = r < front;
      if (ok) { done++; lo = Math.min(lo, gl.x - gl.w / 2); hi = Math.max(hi, gl.x + gl.w / 2); glyph(g, gl, L, {}); }
      else glyph(g, t03Swap(gl, t03Rand(gl.ch, gl.i * 89 + tick * 7, 'sym')), L, { c: K.blue, family: mono, weight: 600, a: .85 });
      if (n <= 14 && L.lines.length === 1 && ok) tx(g, String(r + 1), gl.x, top - 2, { size: 8, f: 'm', w: 500, c: K.mute });
    });
    if (done) {
      const y = bot + 6;
      ln(g, lo, y, hi, y, K.red, 1.5); ln(g, lo, y - 4, lo, y + 1, K.red, 1.5); ln(g, hi, y - 4, hi, y + 1, K.red, 1.5);
    }
    t03Read(g, `interval 50ms · reveal center (${done}/${n})`, 160, 176, K.mute, 'center');
    label(g, '中央から外へ確定');
  },
  descEn: 'All characters keep cycling like ciphertext, then lock in from the centre outward.',
  focus: '暗号の字は 50ms ごとに入れかわり続け、確定が中央の点線から左右へ同時に広がる（上の番号が確定順）。左からの解読と違い、視線が中央に集まる。',
  focusEn: 'The cipher glyphs re-randomise every 50ms while the resolved zone spreads both ways from the dotted centre line (numbers above show the reveal order). Unlike a left-to-right decode, the eye is drawn to the middle.',
  caution: '中央から開くと語頭が最後になるので、英語の長い文では読み始めが遅れる。短い語・ロゴ・数字向き。暗号文字は別書体（等幅）・別色にして、確定済みとはっきり区別する。',
  cautionEn: 'Opening from the centre means the start of the word resolves last, delaying reading on long English phrases — best for short words, logos and numbers. Draw the cipher glyphs in a different face (mono) and colour so they never read as resolved.',
  values: ['interval 50ms', 'revealDirection "center"', 'maxIterations 10', '暗号字は等幅・別色'],
  valuesEn: ['interval 50ms', 'revealDirection "center"', 'maxIterations 10', 'cipher glyphs mono, other colour'],
  duration: 50, easing: 'steps(1)',
  feel: ['硬質'], use: ['見出し', 'ロゴ', 'ゲーム'],
  recipes: {
    css: `/* 画面読み上げには元の文字だけ */
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.cipher { color: var(--accent); font-family: ui-monospace, monospace; }`,
    waapi: `// React Bits DecryptedText 相当（revealDirection: center）
function decrypt(el, text, { speed = 50, chars = '!<>-_\\\\/[]{}=+*^?#' } = {}) {
  const s = Array.from(text), c = (s.length - 1) / 2, done = new Set();
  const order = s.map((_, i) => i).sort((a, b) => Math.abs(a - c) - Math.abs(b - c));
  el.innerHTML = \`<span class="sr-only">\${text}</span><span aria-hidden="true"></span>\`;
  const out = el.lastChild;
  const id = setInterval(() => {
    if (order.length) done.add(order.shift());
    out.innerHTML = s.map((ch, i) => done.has(i) || ch === ' ' ? ch
      : \`<span class="cipher">\${chars[Math.random() * chars.length | 0]}</span>\`).join('');
    if (done.size === s.length) clearInterval(id);
  }, speed);
}`
  }
});

