// 8. 記号フリッカー出現
R({ id: 'char-flicker-in', dur: 3.4, ease: 'linear', still: 2.6,
  f(g, t, o) {
    const L = layout(g, TXT(o), { o, size: 44, y: 92 });
    const gs = L.glyphs, n = gs.length, each = Math.min(.18, 1.6 / (n + 1)), t0 = .3, out = 1 - seg(t, 3.05, 3.3, E.linear);
    let active = -1;
    gs.forEach(gl => {
      if (gl.space) return;
      const d = t0 + (gl.i + 1) * each, u = t - d;
      // 予定地の点
      if (u < 0 || out < 1) alpha(g, u < 0 ? 1 : 1 - out, () => circ(g, gl.x, gl.y + 6, 1.5, K.grid));
      if (u < 0) return;
      // 0.05s 記号 → 0.03s 空白 → 0.05s 別の記号（repeatRefresh）→ 本来の字
      if (u < .05) { active = gl.i; glyph(g, t03Swap(gl, t03Rand(gl.ch, gl.i * 31 + 1, 'flash')), L, { c: K.red, a: out }); }
      else if (u < .08) { active = gl.i; }
      else if (u < .13) { active = gl.i; glyph(g, t03Swap(gl, t03Rand(gl.ch, gl.i * 31 + 2, 'flash')), L, { c: K.red, a: out }); }
      else glyph(g, gl, L, { a: out });
    });
    // 走査マーカー
    if (active >= 0) { const gl = gs[active]; ln(g, gl.x - gl.w / 2, gl.y + 8, gl.x + gl.w / 2, gl.y + 8, K.red, 2); }
    // 1文字ぶんのタイムライン（記号 / 空白 / 記号 / 文字）
    const bx = 98, by = 156, sc = 520;
    [[0, .05, K.red, '#'], [.05, .08, K.grid, ''], [.08, .13, K.red, '%'], [.13, .25, K.ink, 'A']].forEach(([a, b, c, s]) => { rr(g, bx + a * sc, by, (b - a) * sc - 1, 8, 1, c); if (s) tx(g, s, bx + (a + b) / 2 * sc, by + 16, { size: 8, f: 'm', w: 600, c: K.mute }); });
    tx(g, '50ms ×2', bx - 6, by + 4, { a: 'right', size: 9, f: 'm', w: 500, c: K.mute });
    t03Read(g, `delay (i+1) × ${each.toFixed(2)}s`, W - 12, H - 10);
    label(g, '記号が一瞬点滅 → 本来の文字');
  },
  descEn: 'Each character flashes briefly as a random symbol before turning into the real one, and the flicker sweeps left to right.',
  focus: '1文字あたりの点滅はわずか数フレーム。記号 → 空白 → 別の記号 → 本来の字、という短い明滅が左から右へ連鎖していく（下の帯が1文字ぶんの内訳）。',
  focusEn: 'Each flicker lasts only a few frames: symbol → blank → another symbol → the real glyph, chained from left to right (the strip below breaks down one character).',
  caution: '高速の明滅は光過敏の人に負担になりうる。画面全体や大きな面積で使わない・1秒に3回を超える全画面点滅を避ける・動きを減らす設定では無効に。記号は aria-hidden の分割要素の中だけで差しかえる。',
  cautionEn: 'Rapid flashing can be hard on photosensitive viewers: keep it to text, never large areas, avoid full-screen flashes above 3 per second, and disable it under reduced motion. Swap symbols only inside aria-hidden split spans.',
  values: ['flash 0.03〜0.05s × 2', 'delay (i+1) × 0.18s', 'repeat 1 + repeatRefresh', 'opacity 0 → 1'],
  valuesEn: ['flash 0.03–0.05s × 2', 'delay (i+1) × 0.18s', 'repeat 1 + repeatRefresh', 'opacity 0 → 1'],
  duration: 90, easing: 'none',
  feel: ['硬質', 'きびきび'], use: ['見出し', '映像', 'ゲーム'],
  recipes: {
    gsap: `const SYMS = '#%&*+=?@$!<>/|^~';
const split = SplitText.create('.flicker', { type: 'chars', aria: 'auto' });
split.chars.forEach((ch, i) => {
  const orig = ch.textContent;
  gsap.fromTo(ch, { opacity: 0 }, {
    opacity: 1, duration: 0.03, delay: (i + 1) * 0.18,
    innerHTML: () => SYMS[Math.random() * SYMS.length | 0],
    repeat: 1, repeatRefresh: true, repeatDelay: 0.03,
    onComplete: () => { ch.textContent = orig; }
  });
});`,
    css: `/* 記号は ::before で重ね、本来の字は遅れて出す（--i = 文字番号、data-sym = 記号） */
.flicker span { position: relative; opacity: 0; animation: show 0s calc((var(--i) + 1) * .18s + .13s) forwards; }
.flicker span::before { content: attr(data-sym); position: absolute; inset: 0; opacity: 0;
  animation: sym .13s steps(1) calc((var(--i) + 1) * .18s); }
@keyframes sym { 0% { opacity: 1; } 38% { opacity: 0; } 62% { opacity: 1; } 100% { opacity: 0; } }
@keyframes show { to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .flicker span { animation: none; opacity: 1; } .flicker span::before { display: none; } }`
  }
});

