// 9. スロット・シャッフル
R({ id: 'slot-shuffle', dur: 3.4, ease: 'outCubic', still: 2.5,
  f(g, t, o) {
    const L = layout(g, TXT(o), { o, size: 40, y: 90, spacing: .2, maxW: 270 });
    const gs = L.glyphs, n = gs.length, each = Math.min(.06, 1.0 / n), D = .8, m = 7, pitch = L.size * 1.18;
    const aIn = seg(t, 0, .2, E.linear), aOut = 1 - seg(t, 3.0, 3.3, E.linear);
    gs.forEach(gl => {
      if (gl.space) return;
      const cy = gl.y - L.size * .36, bw = gl.w + L.size * .16, bh = L.size * 1.18, x = gl.x - bw / 2, y = cy - bh / 2;
      const s0 = .35 + gl.i * each, pos = (m - 1) * E.outCubic(clamp((t - s0) / D)), vel = (m - 1) * Math.abs(E.outCubic(clamp((t + .01 - s0) / D)) - E.outCubic(clamp((t - s0) / D))) / .01;
      const dir = gl.i % 2 ? -1 : 1;   // 偶数は下へ、奇数は上へ流れる（evenodd）
      rr(g, x, y, bw, bh, 5, K.card, K.grid, 1);
      clip(g, x, y, bw, bh, () => {
        for (let k = Math.floor(pos) - 1; k <= Math.floor(pos) + 1; k++) {
          if (k < 0 || k > m - 1) continue;
          const ch = k === m - 1 ? gl.ch : t03Rand(gl.ch, gl.i * 41 + k * 7, 'up'), dy = (pos - k) * pitch * dir;
          const st = 1 + Math.min(.45, vel * .035);
          glyph(g, t03Swap(gl, ch), L, { dy, sy: st, sx: 1 / Math.sqrt(st), c: k === m - 1 ? K.ink : K.mute, a: aIn * aOut });
        }
      });
      alpha(g, seg(pos, m - 1.2, m - 1, E.linear) * aOut, () => ln(g, x + 3, y + bh + 4, x + bw - 3, y + bh + 4, K.red, 2));
    });
    label(g, 'リールが回って止まる');
    t03Read(g, `evenodd ↓↑ · power3.out ${D}s · stagger ${each.toFixed(2)}s`, 160, 172, K.mute, 'center');
  },
  descEn: 'Each character spins like a slot-machine reel through random letters and stops on the right one.',
  focus: '文字ごとの「窓」の中だけでリールが流れ、止まる直前に減速して正しい字に着地する。偶数番は下へ・奇数番は上へ流れるので、並んだ窓が交互に逆回転して見える。速いあいだは縦に伸びる（モーションブラーの代わり）。',
  focusEn: 'The reel runs only inside each character’s window and decelerates onto the correct glyph. Even slots scroll down and odd slots up, so neighbouring windows counter-rotate. Glyphs stretch vertically while fast, standing in for motion blur.',
  caution: '窓（overflow:hidden）の高さは行の高さに合わせ、字の上下が欠けないように。止まる順番を左から揃えると読みやすい。動きを減らす設定では最初から最終文字を出す。',
  cautionEn: 'Size each window (overflow:hidden) to the line height so ascenders and descenders are not clipped. Stopping left-to-right keeps it readable. Under reduced motion show the final characters immediately.',
  values: ['リール 6 コマ＋最終字', 'power3.out 0.8s', 'stagger 0.06s', 'evenodd：↓ / ↑'],
  valuesEn: ['reel of 6 + final glyph', 'power3.out 0.8s', 'stagger 0.06s', 'evenodd: ↓ / ↑'],
  duration: 800, easing: 'power3.out',
  feel: ['きびきび', '弾む'], use: ['見出し', '広告', 'ゲーム'],
  recipes: {
    css: `/* <span class="reel"><span class="strip"><b>Q</b><b>K</b>…<b>A</b></span></span> */
.reel { display: inline-block; height: 1.2em; overflow: hidden; vertical-align: bottom; }
.strip { display: flex; flex-direction: column; line-height: 1.2em;
  animation: spin .8s cubic-bezier(.215, .61, .355, 1) both; animation-delay: calc(var(--i) * 60ms); }
@keyframes spin { from { transform: translateY(0); } to { transform: translateY(calc(-1.2em * 6)); } }
@media (prefers-reduced-motion: reduce) { .strip { animation: none; transform: translateY(calc(-1.2em * 6)); } }`,
    gsap: `const split = SplitText.create('.slot', { type: 'chars', aria: 'auto' });
const AZ = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
split.chars.forEach((c, i) => {
  const final = c.textContent, strip = document.createElement('span');
  strip.innerHTML = Array.from({ length: 6 }, () => AZ[Math.random() * 26 | 0]).concat(final).map(s => \`<b>\${s}</b>\`).join('');
  c.textContent = ''; c.append(strip); c.style.cssText = 'display:inline-block;height:1.2em;overflow:hidden';
  strip.style.cssText = 'display:flex;flex-direction:column;line-height:1.2em';
  const odd = i % 2;   // evenodd：奇数は逆方向
  gsap.fromTo(strip, { yPercent: odd ? 0 : -6 / 7 * 100 }, { yPercent: odd ? -6 / 7 * 100 : 0, duration: 0.8, ease: 'power3.out', delay: i * 0.06 });
  if (!odd) strip.style.flexDirection = 'column-reverse';
});`
  }
});

