// 10. 文字コード送り
R({ id: 'char-code-cycle', dur: 3.6, ease: 'outQuad', still: 2.6,
  f(g, t, o) {
    const L = layout(g, TXT(o), { o, size: 44, y: 90, spacing: .06 });
    const gs = L.glyphs, n = gs.length, each = Math.min(.12, .9 / n), OFF = 10;
    let maxK = 0;
    gs.forEach(gl => {
      if (gl.space) return;
      // 範囲セレクターのランプ：左から順に 10 → 0。終わりに 0 → 10 へ一気に戻る
      const p = E.outQuad(clamp((t - .4 - gl.i * each) / 1.0)), back = E.inQuad(seg(t, 3.0, 3.5, E.linear));
      const v = OFF * Math.max(1 - p, back), k = Math.ceil(v - 1e-6);
      maxK = Math.max(maxK, k);
      const ch = t03Shift(gl.ch, k);
      glyph(g, t03Swap(gl, ch), L, { c: k ? K.red : K.ink });
      if (k && n <= 16) tx(g, `+${k}`, gl.x, gl.y + 16, { size: 9, f: 'm', w: 600, c: K.mute });
    });
    // 先頭の字のコード表示
    const g0 = gs.find(q => !q.space), cp = g0.ch.codePointAt(0), k0 = (() => { const p = E.outQuad(clamp((t - .4) / 1.0)), back = E.inQuad(seg(t, 3.0, 3.5, E.linear)); return Math.ceil(OFF * Math.max(1 - p, back) - 1e-6); })();
    const hex = c => 'U+' + c.toString(16).toUpperCase().padStart(4, '0');
    const shown = t03Shift(g0.ch, k0).codePointAt(0);
    tx(g, `${g0.ch} ${hex(cp)}  + ${k0}  →  ${hex(shown)}`, 160, 160, { size: 10, f: 'm', w: 600, c: k0 ? K.red : K.mute });
    t03Read(g, `Character Offset ${maxK}`, 160, 178, K.mute, 'center');
    label(g, '文字コードを1つずつ送る');
  },
  descEn: 'Each character steps through neighbouring code points (a → b → c …) and stops on its target letter.',
  focus: '各文字が文字コードの「隣」を1つずつたどって目的の字へ戻る。オフセットが左から順に 10 → 0 になるので、確定の波が左から右へ流れる。ランダムではなく規則的に変わるのがスクランブルとの違い。',
  focusEn: 'Each character walks back through its code-point neighbours to the target; the offset ramps 10 → 0 from the left, so the settling wave travels left to right. The changes are ordered, not random — that is the difference from scramble.',
  caution: '文字コードの隣が「字」とは限らない（記号や未定義の領域に入る）。英字・かな・数字は範囲内で循環させ、それ以外は送らない。和文の漢字は隣のコードが無関係な字になるので、意味のない漢字が一瞬見えることを許容できる場面で。',
  cautionEn: 'A neighbouring code point is not always a letter (it may be punctuation or unassigned). Wrap within a–z, kana and digits and leave other characters alone. For kanji the neighbours are unrelated characters — fine only where meaningless glyphs flashing by is acceptable.',
  values: ['Character Offset 10 → 0', '範囲セレクター：左から', '1.0s ease-out', 'a–z / かな は範囲内で循環'],
  valuesEn: ['Character Offset 10 → 0', 'Range Selector from left', '1.0s ease-out', 'wrap inside a–z / kana'],
  duration: 1000, easing: 'easeOutQuad',
  feel: ['硬質'], use: ['見出し', '映像', 'ロゴ'],
  recipes: {
    canvas: `// a–z / A–Z / かな は範囲内で循環して送る
const RANGES = [[0x61, 0x7a], [0x41, 0x5a], [0x30, 0x39], [0x3041, 0x3093], [0x30a1, 0x30f3]];
const shift = (ch, k) => { const c = ch.codePointAt(0);
  for (const [a, b] of RANGES) if (c >= a && c <= b) return String.fromCodePoint(a + (c - a + k) % (b - a + 1));
  return ch; };
function render(t) {                       // t 秒
  const chars = Array.from(text);
  el.textContent = chars.map((ch, i) => {
    const p = Math.min(1, Math.max(0, (t - i * 0.12) / 1.0)), e = 1 - (1 - p) ** 2;
    return shift(ch, Math.ceil(10 * (1 - e)));
  }).join('');
}`,
    css: `/* 送り中に幅が変わらないよう等幅に */
.cycle { font-family: ui-monospace, monospace; }
@media (prefers-reduced-motion: reduce) { .cycle { /* JS 側で render(Infinity) を一度だけ呼ぶ */ } }`,
    ae: '1. テキストレイヤー → アニメーター追加：文字のオフセット = 10\n2. 文字の範囲：大文字小文字と数字を保持\n3. 範囲セレクター → 高度 → シェイプ：上へ傾斜\n4. オフセット −100% → 100% を 1.5 秒（左から 0 に戻る）',
    aeEn: '1. Text layer → Animate: Character Offset = 10\n2. Character Range: Preserve Case & Digits\n3. Range Selector → Advanced → Shape: Ramp Up\n4. Offset −100% → 100% over 1.5s (offset returns to 0 from the left)'
  }
});

