// 13. 文字の雨
R({ id: 'raining-characters', dur: 4.0, ease: 'outCubic', still: 2.4,
  f(g, t, o) {
    const L = layout(g, TXT(o), { o, size: 44, y: 110 });
    const gs = L.glyphs, n = gs.length;
    // 入り：ランダム順に上から（0.5s ease-out）／出：ランダム順に下へ抜ける（0.45s ease-in）
    const yOf = (gl, tt) => {
      const r = order(gl.i, n, 'random', 11), r2 = order(gl.i, n, 'random', 23);
      const a = .3 + r * 1.0, b = 2.85 + r2 * .55;
      if (tt < b) return -150 * (1 - E.outCubic(clamp((tt - a) / .5))) + (tt < a ? -400 : 0);
      return 150 * E.inCubic(clamp((tt - b) / .45));
    };
    t03Floor(g, L, 14, K.grid);
    gs.forEach(gl => {
      if (gl.space) return;
      // エコー：33ms ずつ遅れた 3 つの残像（50 / 35 / 20%）
      [3, 2, 1].forEach(k => { const dy = yOf(gl, t - k * .033), d0 = yOf(gl, t); if (Math.abs(dy - d0) > 1.5) glyph(g, gl, L, { dy, c: K.red, a: [0, .5, .35, .2][k] }); });
      const dy = yOf(gl, t);
      glyph(g, gl, L, { dy, a: clamp(1 - Math.max(0, dy) / 150) });
    });
    t03Read(g, 'Randomize Order · Echo ×3 / 33ms', 160, 186, K.mute, 'center');
    label(g, 'ランダム順に降る＋残像');
  },
  descEn: 'Characters rain down from above in random order and click into place, trailing short echoes while they fall.',
  focus: '落ちる順番はランダム、でも着地する場所は最初から決まっている。落下中だけ 33ms 遅れの残像（強調色）が3本尾を引き、止まると消えるので「速さ」だけが見える。最後は同じ雨で下へ抜ける。',
  focusEn: 'The order is random but every character lands in its fixed slot. Three echoes trailing 33ms apart (accent colour) appear only while falling and vanish on landing, so they read purely as speed. It exits the same way, raining out downward.',
  caution: 'ランダム順は「読む順」とずれるので、全文字が止まってから読ませる時間（0.8s 以上）を必ず取る。残像を濃くしすぎると文字が二重に見える（30〜50% が目安）。',
  cautionEn: 'Random order fights reading order, so always leave ≥0.8s of fully settled text. Echoes that are too strong look like double vision — keep them around 30–50%.',
  values: ['順番：ランダム', '落下 0.5s ease-out', '残像 3 本 / 33ms 遅れ', '残像の濃さ 50 → 20%'],
  valuesEn: ['order: random', 'fall 0.5s ease-out', '3 echoes, 33ms apart', 'echo opacity 50 → 20%'],
  duration: 500, easing: 'easeOutCubic',
  feel: ['なめらか', 'きびきび'], use: ['見出し', '映像'],
  recipes: {
    gsap: `const split = SplitText.create('.rain', { type: 'chars', aria: 'auto' });
gsap.from(split.chars, { y: -150, autoAlpha: 0, duration: 0.5, ease: 'power3.out',
  stagger: { each: 0.06, from: 'random' } });
// 残像：同じ文字のコピーを 33ms ずつ遅らせて半透明で重ねる（filter: blur でも代用可）`,
    canvas: `// f(t) で描くなら、残像は「少し前の時刻の位置」をもう一度描くだけ
function drawChar(ch, x, yAt, t) {
  [3, 2, 1].forEach((k, j) => { ctx.globalAlpha = [0.2, 0.35, 0.5][j]; ctx.fillText(ch, x, yAt(t - k * 0.033)); });
  ctx.globalAlpha = 1; ctx.fillText(ch, x, yAt(t));
}`,
    ae: '1. エフェクト＆プリセット → Animate In → Raining Characters In を適用\n2. 範囲セレクター → 高度 → 順序をランダム化：オン（ランダムシードで並びを変更）\n3. 位置の Y（例 −300）と範囲のオフセットで落下距離・速さを調整\n4. エフェクト → 時間 → エコー：エコー時間 −0.033、エコーの数 3、減衰 0.6',
    aeEn: '1. Effects & Presets → Animate In → Raining Characters In\n2. Range Selector → Advanced → Randomize Order: On (change Random Seed for a new order)\n3. Tune fall distance/speed with Position Y (e.g. −300) and the range Offset\n4. Effect → Time → Echo: Echo Time −0.033, Number of Echoes 3, Decay 0.6'
  }
});

// =====================================================================
// 14. 落下して積もる
// 高さ H から重力 ga で落ち、反発係数 e で跳ねる。戻り値 = 着地点からの高さ
function t03Fall(s, Hh, ga, e) {
  if (s <= 0) return Hh;
  const T = Math.sqrt(2 * Hh / ga); if (s < T) return Hh - .5 * ga * s * s;
  let v = ga * T * e, u = s - T;
  for (let k = 0; k < 5; k++) { const d = 2 * v / ga; if (u < d) return v * u - .5 * ga * u * u; u -= d; v *= e; }
  return 0;
}
// 単語（3語未満なら文字）を床に積む配置
function t03Pile(g, o, text) {
  const ws = words(text).filter(w => !/^\s+$/.test(w));
  const units = ws.length >= 3 ? ws : graphemes(text).filter(c => !/\s/.test(c));
  const fam = FAM(o), wt = WGT(o), FLOOR = 170;
  let size = 24, items, rows;
  for (let guard = 0; guard < 20; guard++) {
    items = units.map(u => ({ u, w: textW(g, u, size, wt, fam) + size * .7, h: size * 1.3 }));
    const tot = items.reduce((a, it) => a + it.w + 4, 0), cap = Math.max(...items.map(it => it.w), Math.min(270, tot * .6));
    rows = [[]]; let rw = 0;
    items.forEach(it => { if (rows[rows.length - 1].length && rw + it.w + 4 > cap) { rows.push([]); rw = 0; } rows[rows.length - 1].push(it); rw += it.w + 4; });
    if (rows.length * items[0].h <= 112 || size < 9) break;
    size *= .9;
  }
  rows.forEach((row, r) => {
    const tot = row.reduce((a, it) => a + it.w + 4, -4); let x = 160 - tot / 2 + (r % 2 ? 6 : 0);
    row.forEach((it, j) => { it.x = x + it.w / 2; it.y = FLOOR - it.h * (r + .5) - r * 1; it.r = r; it.rest = r ? (hash(r * 13 + j * 7) - .5) * .14 : 0; x += it.w + 4; });
  });
  const all = rows.flat(); all.forEach((it, j) => { it.j = j; });
  return { items: all, size, fam, wt, FLOOR, word: ws.length >= 3 };
}
R({ id: 'falling-pile', dur: 4.4, ease: 'inQuad', still: 3.2,
  f(g, t, o) {
    const P = t03Pile(g, o, TXT(o)), m = P.items.length, each = Math.min(.2, 1.5 / m), ga = 1500, e = .4;
    const exitS = Math.max(0, t - 3.75), fallOut = .5 * 1600 * exitS * exitS, aOut = 1 - seg(t, 3.85, 4.25, E.linear);
    ln(g, 20, P.FLOOR + .5, 300, P.FLOOR + .5, K.mute, 1);
    const land = P.items.map(it => { const H0 = it.y + it.h + 30 + hash(it.j * 3.3) * 50; return { H0, t: .3 + it.j * each + Math.sqrt(2 * H0 / ga) }; });
    P.items.forEach((it, j) => {
      const rel = .3 + j * each, s = t - rel, H0 = land[j].H0, hgt = t03Fall(s, H0, ga, e);
      const T = Math.sqrt(2 * H0 / ga), fp = clamp(s / T);
      const x0 = it.x + (hash(j * 5.1) - .5) * 50, x = lerp(x0, it.x, E.outQuad(fp));
      const a0 = (hash(j * 9.7) - .5) * 1.2, ang = s < T ? a0 * (1 - fp * .3) : it.rest + (a0 * .7 - it.rest) * Math.exp(-(s - T) * 7) * Math.cos((s - T) * 16);
      // 上に積まれた語の着地で、下の段が少し沈む
      let jolt = 0;
      P.items.forEach((q, k) => { if (q.r > it.r && Math.abs(q.x - it.x) < (q.w + it.w) / 2) { const d = t - land[k].t; if (d > 0) jolt += 2.4 / (q.r - it.r) * Math.exp(-d * 12) * Math.sin(d * 34); } });
      const y = it.y - hgt + jolt + fallOut;
      if (y < -it.h) return;
      alpha(g, aOut, () => xf(g, x, y, 1, 1, ang, () => {
        const hot = j === 0;
        rr(g, -it.w / 2, -it.h / 2, it.w, it.h, it.h * .3, hot ? K.red : K.card, hot ? null : K.line, 1);
        setFont(g, P.size, P.wt, P.fam); g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillStyle = hot ? K.paper : K.ink; g.fillText(it.u, 0, 1);
      }));
    });
    t03Read(g, `gravity 1 · restitution ${e} · unit: ${P.word ? 'word' : 'char'} ×${m}`, 160, 186, K.mute, 'center');
    label(g, '重力で落下 → 積み重なる');
  },
  descEn: 'Words fall under gravity, knock into each other, bounce and pile up at the bottom of the frame.',
  focus: '語は ½gt² で加速して落ち、反発係数ぶんだけ低く跳ねて止まる。上の段の語が着地すると、真下の語がわずかに沈む——この「受け止め」があると積み重なりに重さが出る。',
  focusEn: 'Words accelerate at ½gt², rebound by the restitution factor and settle. When a word lands on the upper row, the word underneath dips slightly — that give is what makes the pile feel heavy.',
  caution: '物理演算は毎回結果が変わるので、読ませたい順に並ぶとは限らない。見出しの意味を伝える用途より、落ちた後に触って遊べるインタラクションや「崩れる」演出向き。物理を止めた静止版（並んだ状態）を reduced-motion 用に用意する。',
  cautionEn: 'Real physics gives a different heap every time, so words rarely end in reading order — use it for playful, touchable moments or a “collapse” beat rather than to convey a headline. Provide a static, in-order version for reduced motion.',
  values: ['gravity 1（½gt²）', 'restitution 0.4', '落下の時間差 0.2s', '着地の衝撃で下段が沈む'],
  valuesEn: ['gravity 1 (½gt²)', 'restitution 0.4', 'drop stagger 0.2s', 'lower row dips on impact'],
  duration: 600, easing: 'gravity (½gt²)',
  feel: ['重い', '弾む'], use: ['広告', 'ゲーム', '見出し'],
  recipes: {
    canvas: `// Matter.js：単語ごとに剛体を作り、DOM の transform を同期（React Bits FallingText 方式）
const { Engine, Bodies, Composite, Runner } = Matter;
const engine = Engine.create(); engine.gravity.y = 1;
const box = el.getBoundingClientRect();
const floor = Bodies.rectangle(box.width / 2, box.height + 25, box.width, 50, { isStatic: true });
const bodies = [...el.querySelectorAll('.word')].map(w => {
  const r = w.getBoundingClientRect();
  const b = Bodies.rectangle(r.left - box.left + r.width / 2, r.top - box.top, r.width, r.height, { restitution: 0.4, frictionAir: 0.01 });
  return { w, b, r };
});
Composite.add(engine.world, [floor, ...bodies.map(x => x.b)]);
Runner.run(Runner.create(), engine);
(function sync() {
  bodies.forEach(({ w, b, r }) => { w.style.transform = \`translate(\${b.position.x - r.width / 2}px, \${b.position.y - r.height / 2}px) rotate(\${b.angle}rad)\`; });
  requestAnimationFrame(sync);
})();`,
    css: `.falling { position: relative; height: 240px; overflow: hidden; }
.falling .word { position: absolute; left: 0; top: 0; will-change: transform; padding: .1em .4em; border-radius: .4em; }
@media (prefers-reduced-motion: reduce) { .falling .word { position: static; transform: none !important; } }`
  }
});

