    const ax = Math.min(34, home[0][0] - 24), ay = Math.min(54, home[0][1] - L.size * .8 - 24);
    const lead = tau => { const e = E.inOut(clamp((tau - .35) / 1.9)); return [ax * Math.sin(TAU * e), -ay * Math.sin(Math.PI * e)]; };
    const S = t03Chain(t, home, lead, .2, .6, gs.map((q, i) => i > 0 && q.li !== gs[i - 1].li)), n = gs.length;
    // 先頭の軌跡（ゴースト）
