// 20. パーティクル文字
const t03PC = new Map();
function t03Particles(o, text) {
  const key = text + '|' + ((o && o.font) || 'sans');
  if (t03PC.has(key)) return t03PC.get(key);
  let res = null;
  try {
    const S = 2, c = document.createElement('canvas'); c.width = W * S; c.height = H * S;
    const lg = c.getContext('2d'); lg.scale(S, S);
    const L = layout(lg, text, { o, size: 80, maxW: 284, maxLines: 2, weight: 900, y: 100 });
    lg.fillStyle = K.ink; setFont(lg, L.size, L.weight, L.family); lg.textAlign = 'center'; lg.textBaseline = 'middle';
    L.glyphs.forEach(gl => { if (!gl.space) lg.fillText(gl.ch, gl.x, gl.y - L.size * .36); });
    const d = lg.getImageData(0, 0, c.width, c.height).data, step = clamp(L.size / 24, 2.1, 3.4), pts = [];
    for (let y = step / 2, row = 0; y < H; y += step, row++) for (let x = step / 2 + (row % 2) * step / 2; x < W; x += step) {
      if (d[(Math.round(y * S) * c.width + Math.round(x * S)) * 4 + 3] > 128) pts.push([x, y]);
    }
    res = { pts, L, step };
  } catch (e) { res = null; }
  if (t03PC.size > 24) t03PC.clear();
  t03PC.set(key, res);
  return res;
}
// ばね（ω=10, ζ=0.45）のインパルス応答で「押されて戻る」を時刻だけから計算する
const t03IR = (() => { const w = 10, z = .45, wd = w * Math.sqrt(1 - z * z), dt = .04; return Array.from({ length: 22 }, (_, j) => { const tau = j * dt + dt / 2; return [tau, Math.exp(-z * w * tau) * Math.sin(wd * tau) / wd * dt]; }); })();
