    const keys = [[0, 336, 200], [.35, 336, 200], [1.1, xl + T.width * .18, cy + 30], [2.0, xr - T.width * .22, cy - 18], [2.6, xr - T.width * .08, cy + 14], [3.35, 336, 206], [4.2, 336, 200]];
