    if (on) { g.setLineDash([3, 4]); circ(g, cx, cyy, R0, null, t08A(K.red, .5), 1); g.setLineDash([]); }
    const dt = 1 / 30, t1 = Math.floor(t / dt) * dt;
    T.glyphs.forEach(gl => {
      if (gl.space) return;
      const hx = gl.x, hy = t08Cy(gl, T);
      // 最後に「乱れ」を受けてからの残り時間（遠いほど短い）
      let left = 0;
      for (let k = 0; k * dt < D; k++) { const s = t1 - k * dt, [px, py] = cur(s), d = Math.hypot(px - hx, py - hy); if (d < R0) left = Math.max(left, D * (1 - d / R0) - (t - s)); }
      if (left > 0) {
        glyph(g, gl, T, { c: K.grid, a: .55 });
        const ch = hash(gl.i * 13.7 + Math.floor(t / .08)) < .5 ? '.' : ':';
        glyph(g, Object.assign({}, gl, { ch }), T, { c: K.red, family: FAM(o, 'm'), weight: 700 });
        const bw = Math.min(gl.w * .9, 18) * (left / D);
        rr(g, hx - bw / 2, gl.y + T.size * .2, bw, 2, 1, t08A(K.red, .8));
      } else glyph(g, gl, T, { c: K.ink });
    });
    if (on) cursor(g, cx, cyy);
    t08M(g, 'radius 100 · chars ".:"', 12, 186);
    t08M(g, 'duration 1.2 × (1 − d/r)', 308, 186, { a: 'right' });
