// 6. カーソル軌跡テキスト
const t08Trail = (() => {
  // 波の道のり（u = 0..1）と、等間隔スタンプの時刻を前もって計算
  const P = u => [26 + 268 * u, 104 + 42 * Math.sin(u * TAU * 1.15 + .4) * (1 - .25 * u)];
  const ta = .3, tb = 2.9, pts = [], cache = {};
  for (let k = 0; k <= 120; k++) pts.push(P(k / 120));
  // 間隔ごとのスタンプ時刻（入力語の幅で間隔が変わるのでメモしておく）
  const stampsFor = spacing => {
    if (cache[spacing]) return cache[spacing];
    let acc = 0, prev = P(0), next = spacing; const stamps = [];
    for (let k = 0; k <= 520; k++) {
      const tt = ta + (tb - ta) * k / 520, u = E.inOut(k / 520), p = P(u);
      acc += Math.hypot(p[0] - prev[0], p[1] - prev[1]);
      if (acc >= next) { const q = P(Math.min(1, u + .004)); stamps.push({ t: tt, x: p[0], y: p[1], ang: Math.atan2(q[1] - p[1], q[0] - p[0]) }); next += spacing; }
      prev = p;
    }
    return (cache[spacing] = stamps);
  };
  return { P, ta, tb, stampsFor, pts };
})();
