      // 退場：8 枚目が出たら最古から / 止まったら 30ms ごとに古い順
      const evict = k + MAXN < stamps.length ? stamps[k + MAXN].t : Infinity;
      const tIdle = idle + k * .03, tExit = Math.min(evict, tIdle), age = t - s.t;
      const ex = seg(t, tExit, tExit + .5, E.outQuad);
