    const m = g.getTransform(), bg = t08Buf.getContext('2d');
    bg.setTransform(1, 0, 0, 1, 0, 0); bg.globalAlpha = 1; bg.filter = 'none'; bg.clearRect(0, 0, t08Buf.width, t08Buf.height); bg.setTransform(m);
