    const N = n || (lang === 'en' ? { pre: '$', post: '', value: 182.4, dec: 2, group: true } : { pre: '¥', post: '', value: 3512, dec: 0, group: true });
    const sym = n ? '' : s;
    const pre = N.pre.replace(/^\s+/, ''), post = N.post.replace(/[▲▼△▽↑↓]/g, '').trim();
    const unit = Math.pow(10, -N.dec), v0 = N.value;
    const d = Math.max(unit, Math.round(Math.abs(v0) * .0065 / unit) * unit), v1 = v0 + d, v2 = v0 - Math.max(unit, Math.round(d * .6 / unit) * unit);
