    let k = 0; times.forEach((tt, i) => { if (t >= tt) k = i + 1; });
    const fmt = v => pre + t08Fmt(v, N.dec, N.group || Math.abs(v0) >= 10000) + (post ? ' ' + post : '');
    const cur = fmt(seq[k]), old = k ? fmt(seq[k - 1]) : cur, tu = k ? times[k - 1] : -9, dir = k ? Math.sign(seq[k] - seq[k - 1]) : 1;
    const fam = FAM(o), wt = WGT(o);
    const size = t08Fit(g, fmt(Math.max(v1, v0)), 220, 50, fam, wt);
    const C = t08Tab(g, cur, size, fam, wt), O = t08Tab(g, old, size, fam, wt), Fm = t08Tab(g, fmt(Math.max(v1, v0)), size, fam, wt);
    const cy = sym ? 92 : 86, base = cy + size * .36, right = 160 + Fm.total / 2 - 12;
    const col = dir > 0 ? K.green : K.red, fl = 1 - seg(t, tu, tu + .6, E.outQuad), sl = seg(t, tu, tu + .35, E.outCubic);
